import six
import logging
from abc import ABCMeta, abstractmethod

from typing import Optional, Sequence, Union, List, Any  # noqa: F401

from taf.config.testline.connection_details import SshServiceDetails  # noqa: F401
from .pdu import PduPort  # noqa: F401
from .airscale import Airscale  # noqa: F401
from .system_module import SystemModule  # noqa: F401
from .radio import RadioModule, RU  # noqa: F401
from .gnb.networkaddress import NetworkAddress  # noqa: F401
from .gnb.du import Cablink, VDU  # noqa: F401
from .cloud_hosting import CloudDeployment  # noqa: F401
from .dcap import DcapRnD, DcapBasic  # noqa: F401


@six.add_metaclass(ABCMeta)
class Enb(object):
    @abstractmethod
    def __init__(self, instance_id=None, global_bts_id=None, dcap=None):
        # type: (Optional[int], Optional[int], Optional[Union[DcapRnD, DcapBasic]]) -> None
        """

        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to enb
        """
        self.instance_id = instance_id
        self.global_bts_id = global_bts_id
        self.dcap = dcap


@six.add_metaclass(ABCMeta)
class SimEnb(Enb):
    @abstractmethod
    def __init__(self, instance_id=None, global_bts_id=None):
        # type: (Optional[int], Optional[int]) -> None
        """

        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        """
        super(SimEnb, self).__init__(instance_id=instance_id, global_bts_id=global_bts_id)


# TODO: replace airscale parameter with system_module mandatory parameter with next major release
class RealEnb(Enb):
    def __init__(self,
                 airscale=None,         # type: Airscale
                 rms=None,              # type: Optional[Sequence[Union[RadioModule, RU]]]
                 x2_link_addr=None,     # type: Optional[Union[str, NetworkAddress]]
                 instance_id=None,      # type: Optional[int]
                 global_bts_id=None,    # type: Optional[int]
                 system_module=None,    # type: Optional[SystemModule]
                 oam_ip=None,           # type: Optional[NetworkAddress]
                 slave=None,            # type: Optional[Any]
                 master=None,           # type: Optional[Any]
                 bcf_id=None,           # type: Optional[str]
                 cablinks=None,         # type: Optional[List[Cablink]]
                 dcap=None,             # type: Optional[Union[DcapRnD, DcapBasic]]
                 trs_ip=None,           # type: Optional[NetworkAddress]
                 top_ip=None            # type: Optional[NetworkAddress]
                 ):
        """
        :param Optional[Airscale] airscale: Airscale object class
        :param Optional[List[Union[RadioModule_co, RU_co]]] rms: List of objects of Radio module classes or subclasses
        :param Optional[Union[str, NetworkAddress]] x2_link_addr: ip address to LNADJGNB
        :param Optional[int] instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param Optional[int] global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        :param Optional[SystemModule_co]system_module: Instance of SystemModule child class
        :param Optional[NetworkAddress] oam_ip: OAM IP (MPLANE IP) of the eNB
        :param Optional[Any] master: Another gNB, eNB, nB or Bts2G
          which is connected to it in master role
        :param Optional[Any] slave: Another gNB, eNB, nB or Bts2G
          which is connected to it in slave role
        :param Optional[str] bcf_id: BCF ID of the SBTS configuration
        :param Optional[List[Cablink]] cablinks: List of objects of Cablink classes
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to enb
        :param Optional[NetworkAddress] trs_ip: TRS IP (Backhaul IP) of the eNB
        :param Optional[NetworkAddress] top_ip: TOP IP used by the eNB
        """
        if isinstance(x2_link_addr, str):
            logging.warning("[Deprecation Warning] Since taf.config.testline 8.9 'x2_link_addr' parameter "
                            "should be an instance of taf.config.testline.gnb.networkaddress.NetworkAddress "
                            "class. Please adapt your code as soon as possible.")

        if airscale is not None:
            logging.warning('[Deprecation Warning] Airscale param in RealEnb is depracated. '
                            'Put Airscale instances into system_module param.')
        super(RealEnb, self).__init__(instance_id=instance_id, global_bts_id=global_bts_id, dcap=dcap)
        self.airscale = airscale
        self.rms = rms
        self.x2_link_addr = x2_link_addr
        self.instance_id = instance_id
        self.system_module = system_module
        self.oam_ip = oam_ip
        self.slave = slave
        self.master = master
        self.bcf_id = bcf_id
        self.cablinks = cablinks
        self.trs_ip = trs_ip
        self.top_ip = top_ip


class LTEEmuEnb(SimEnb):
    def __init__(self, default_ssh_connection_details, dir_path, cfg_filename,
                 instance_id=None, global_bts_id=None, x2_link_addr=None):
        # type: (SshServiceDetails, str, str, Optional[int], Optional[int], Optional[NetworkAddress]) -> None
        """
        :param SshServiceDetails default_ssh_connection_details: SshServiceDetails class instance object
        :param str dir_path:
        :param str cfg_filename:
        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        :param x2_link_addr: (optional) Address assigned to x2 interface of this eNB.
        """

        super(LTEEmuEnb, self).__init__(instance_id=instance_id, global_bts_id=global_bts_id)
        self.default_ssh_connection_details = default_ssh_connection_details
        self.dir_path = dir_path
        self.cfg_filename = cfg_filename
        self.x2_link_addr = x2_link_addr

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


class PrismaEnb(SimEnb):
    def __init__(self, tstm_x2_ssh_connection_details, instance_id=None, global_bts_id=None):
        # type: (SshServiceDetails, Optional[int], Optional[int]) -> None
        """

        :param tstm_x2_ssh_connection_details: SshServiceDetails class instance object
        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        """
        super(PrismaEnb, self).__init__(instance_id=instance_id, global_bts_id=global_bts_id)
        self.tstm_x2_ssh_connection_details = tstm_x2_ssh_connection_details

    def __taf_contract_ssh__(self):
        return self.tstm_x2_ssh_connection_details.__taf_contract_ssh__()


class DocomoEnb(Enb):

    def __init__(
            self,
            default_ssh_connection_details,    # type: SshServiceDetails
            pdu_port=None,                     # type: Optional[PduPort]
            instance_id=None,                  # type: Optional[int]
            global_bts_id=None                 # type: Optional[int]
    ):
        """
        :param SshServiceDetails default_ssh_connection_details: SshServiceDetails class instance object
        :param PduPort pdu_port: pdu port of enb
        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        """
        super(DocomoEnb, self).__init__(instance_id=instance_id, global_bts_id=global_bts_id)
        self.default_ssh_connection_details = default_ssh_connection_details
        self.pdu_port = pdu_port

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


# Note: Until the latter model is confirmed to be correct (including the lack
# of anything CU-related in this model), to ensure there's room for
# backward-compatibility, the keyword arguments of this class have been made
# keyword-only. The `cloud_deployment` arg, positional in `CloudBts` class (5G
# analog of this model) has been made keyword-only too. If we find out the
# model is missing an argument, this will allow us to add this argument in the
# right order without breaking compatibility.
#
# TODO: Once we confirm the model is correct, we can consider removing the
# keyword-only restriction.
class Cloud4gBts(Enb):
    def __init__(self,
                 du,  # type: VDU
                 *,
                 cloud_deployment,  # type: CloudDeployment
                 vnf_name=None,  # type: Optional[str]
                 instance_id=None,  # type: Optional[int]
                 global_bts_id=None,  # type: Optional[int]
                 dcap=None  # type: Optional[Union[DcapRnD, DcapBasic]]
                 ):
        """

        :param VDU du: VDU object represinting the VDU that forms the veNB.
        :param CloudDeployment cloud_deployment: CloudDeployment class instance object
        :param str vnf_name: Name of the vnf (Virtual Network Function)
        :param int instance_id: instance_id parameter is deprecated and will be removed in the future.
        :param int global_bts_id: global_bts_id parameter is deprecated and will be removed in the future.
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to gnb
        """
        super().__init__(instance_id=instance_id, global_bts_id=global_bts_id, dcap=dcap)
        self.du = du
        self.vnf_name = vnf_name
        self.cloud_deployment = cloud_deployment

        if self.instance_id is not None:
            logging.warning('instance_id parameter is deprecated and will be removed in the future. '
                            'For CloudBts configuration, instance_id should be defined separately for CU and DUs.')
        if self.global_bts_id is not None:
            logging.warning('global_bts_id parameter is deprecated and will be removed in the future. '
                            'For CloudBts configuration, global_bts_id should be defined separately for CU and DUs.')

    @property
    def oam_ip(self):
        oam_ip = 'oam_ip'
        params = 'parameters'

        def has_oam_ip(configuration):
            return (configuration is not None
                    and params in configuration
                    and oam_ip in configuration[params])

        vnfs = [vnf for vnf in self.cloud_deployment.vnfs
                if has_oam_ip(vnf.configuration_data)]

        if len(vnfs):
            # We are returning oam ip from the first vnf because we
            # assume that every vnf has the same exact oam ip value.
            return vnfs[0].configuration_data[params][oam_ip]
